# =====================================================================
#  finance.map - phishing phrases for banks, insurance and accounting
#  Part of: phishing-detector by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : fake SWIFT / MT103 payment copies, proof of payment and
#           remittance lures, blocked cards and online banking,
#           pending / held wire transfers, tax authority notices and
#           refunds, audit and compliance (KYC) requests, insurance
#           claims and policy notices, urgent CEO payment requests (BEC),
#           accounting-software invoice lures
#
#  Avoided: "invoice attached", "payment received", "monthly statement
#           is available", because companies get real ones every day.
# =====================================================================

# ===== English =====
# Fake payment copies
/(swift|mt\s?103)\s+(copy|confirmation|message|slip)\s+(attached|of\s+(the\s+)?payment|for\s+your\s+review)/i
/(view|download|open)\s+(the\s+)?(proof\s+of\s+payment|payment\s+receipt|remittance\s+advice|payment\s+advice)/i
/(payment|transfer)\s+(copy|confirmation)\s+(is\s+)?(available|ready)\s+(for\s+download|online|here)/i
# Blocked cards / online banking
/your\s+(credit\s+card|debit\s+card|card|bank\s+account)\s+(has\s+been|was|is)\s+(temporarily\s+)?(blocked|suspended|restricted|frozen|locked)/i
/(online|internet|mobile)\s+banking\s+(access\s+)?(has\s+been\s+)?(suspended|locked|blocked|disabled)/i
/(update|reactivate|verify)\s+your\s+(security\s+token|otp\s+device|3-?d\s+secure|banking\s+details)/i
/unusual\s+(transaction|card\s+activity)\s+(detected|on\s+your\s+account)/i
# Held transfers
/(wire|incoming|international)\s+transfer\s+(is\s+)?(pending|on\s+hold|held|awaiting)\s+(your\s+)?(approval|confirmation|verification|release)/i
/(funds|payment)\s+(are\s+|is\s+)?(on\s+hold|held)\s+(pending|until)\s+(verification|confirmation)/i
# Tax authority
/(tax|vat)\s+(refund|rebate)\s+(of\s+[\d.,]+\s+\S+\s+)?(is\s+)?(approved|pending|available|ready)/i
/(outstanding|unpaid|overdue)\s+tax\s+(debt|liability|balance|payment)/i
/(irs|hmrc|tax\s+authority|revenue\s+service|tax\s+office)\s+(notice|notification|penalty|audit)/i
# Audit / compliance
/(audit|compliance|aml)\s+(documents?|request|review)\s+(is\s+|are\s+)?(required|pending|overdue)/i
/kyc\s+(verification|documents?|update|review)\s+(is\s+)?(required|pending|expired|overdue)/i
# Insurance
/insurance\s+claim\s+(#?\d+\s+)?(has\s+been\s+)?(approved|rejected|pending|requires\s+(your\s+)?action)/i
/(your\s+)?policy\s+(will\s+be\s+|has\s+been\s+)?(cancelled|canceled|suspended|terminated)\s+(due\s+to|unless|today)/i
# BEC / urgent payments
/urgent\s+(wire|payment|transfer|remittance)\s+request/i
/(process|make)\s+(an\s+)?urgent\s+(wire|payment|transfer)\s+(today|immediately|before)/i
/(i\s+am|i'm)\s+(in\s+a\s+meeting|traveling|travelling|unavailable)[^.]{0,40}\s+(urgent|payment|transfer|wire)/i
# Accounting software lures
/(quickbooks|xero|sage|freshbooks|zoho\s+books)\s+(invoice|payment|statement)\s+(notification|is\s+ready|overdue|reminder)/i

